-- migration_005: Facebook directory groups and the kevinzg/facebook-scraper bridge

CREATE TABLE IF NOT EXISTS facebook_groups (
  id              SERIAL PRIMARY KEY,
  group_id        TEXT NOT NULL UNIQUE,
  name            TEXT NOT NULL,
  url             TEXT NOT NULL,
  category        TEXT NOT NULL,
  categories      JSONB NOT NULL DEFAULT '[]',
  essential       BOOLEAN NOT NULL DEFAULT FALSE,
  tier            SMALLINT NOT NULL,
  language        TEXT,
  confidence      TEXT,
  members         TEXT,
  directory_row   SMALLINT,
  enabled         BOOLEAN NOT NULL DEFAULT TRUE,
  last_scraped_at TIMESTAMPTZ,
  last_status     TEXT,
  last_error      TEXT,
  post_count      INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_facebook_groups_selection
  ON facebook_groups(enabled, essential DESC, tier, confidence, name);

ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  color = EXCLUDED.color,
  base_url = EXCLUDED.base_url;

-- Generated from backend/data/facebook_groups.json. Keep both files in sync.
ON CONFLICT (group_id) DO UPDATE SET
  name = EXCLUDED.name,
  url = EXCLUDED.url,
  category = EXCLUDED.category,
  categories = EXCLUDED.categories,
  essential = EXCLUDED.essential,
  tier = EXCLUDED.tier,
  language = EXCLUDED.language,
  confidence = EXCLUDED.confidence,
  members = EXCLUDED.members,
  directory_row = EXCLUDED.directory_row;

